  const org = await client.organizations.get?.() ?? null;
  return { ctx, org };
}

export default async (ctx, client) => {
  const failing = await client.feeds.list({ health: 'failing', limit: 100 });
  const all = await client.feeds.list({ limit: 200 });
  return {
    failing_count: failing.total ?? failing.feeds?.length,
    failing: (failing.feeds ?? []).map(f => ({ id: f.id, key: f.feed_key, conn: f.connection_id, status: f.status, last_sync: f.last_sync_at ?? f.last_synced_at, err: f.last_error ?? f.error_message })),
    total_feeds: all.total ?? all.feeds?.length,
    by_status: (all.feeds ?? []).reduce((a, f) => (a[f.status] = (a[f.status]||0)+1, a), {}),
  };
}

