export default async (ctx, client) => {
  const since = new Date(Date.now() - 7*24*3600*1000).toISOString();
  const runs = await client.operations.listRuns({ created_after: since, limit: 500 });
  const list = runs.runs ?? runs.items ?? runs;
  const agg = {};
  for (const r of list) {
    const k = `${r.run_type ?? r.type}|${r.status}`;
    agg[k] = (agg[k] ?? 0) + 1;
  }
  const failed = list.filter(r => String(r.status).match(/fail|error|timeout/i))
    .slice(0, 20)
    .map(r => ({ id: r.id, type: r.run_type ?? r.type, status: r.status, behavior_id: r.behavior_id, connector: r.connector_key, op: r.operation_key, err: (r.error ?? r.error_message ?? '').toString().slice(0,200), at: r.created_at }));
  return { total: list.length, agg, failed_sample: failed };
}

export default async (ctx, client) => {
  const since = new Date(Date.now() - 7*24*3600*1000).toISOString();
  const agg = {}; const failed = {};
  let offset = 0, total = 0;
  for (let page = 0; page < 10; page++) {
    const r = await client.operations.listRuns({ created_after: since, limit: 200, offset });
    const list = r.runs ?? r.items ?? [];
    if (!list.length) break;
    total += list.length;
    for (const x of list) {
      const k = `${x.run_type ?? x.type}|${x.status}`;
      agg[k] = (agg[k] ?? 0) + 1;
      if (/fail|error|timeout/i.test(String(x.status))) {
        const fk = `${x.run_type ?? x.type}|${x.behavior_id ?? x.connector_key ?? x.operation_key ?? '?'}|${String(x.error ?? x.error_message ?? '').slice(0,120)}`;
        failed[fk] = (failed[fk] ?? 0) + 1;
      }
    }
    offset += list.length;
    if (list.length < 200) break;
  }
  return { total, agg, failed };
}

export default async (ctx, client) => {
  const since = new Date(Date.now() - 3*24*3600*1000).toISOString();
  const out = {};
  for (const st of ['failed', 'error', 'completed', 'running']) {
    try {
      const r = await client.operations.listRuns({ created_after: since, status: st, limit: 5 });
      const list = r.runs ?? r.items ?? [];
      out[st] = { total: r.total ?? null, sample: list.slice(0,5).map(x => ({ id: x.id, t: x.run_type ?? x.type, b: x.behavior_id, c: x.connector_key, op: x.operation_key, at: x.created_at, err: String(x.error ?? x.error_message ?? '').slice(0,150) })) };
    } catch (e) { out[st] = { err: String(e).slice(0,200) }; }
  }
  return out;
}

export default async (ctx, client) => {
  const since = new Date(Date.now() - 3*24*3600*1000).toISOString();
  const agg = {};
  let offset = 0;
  for (let p = 0; p < 8; p++) {
    const r = await client.operations.listRuns({ created_after: since, status: 'failed', limit: 40, offset });
    const list = r.runs ?? r.items ?? [];
    if (!list.length) break;
    for (const x of list) {
      const k = `${x.run_type ?? x.type} | ${x.connector_key ?? 'behavior:' + x.behavior_id} | ${x.operation_key ?? ''}`;
      agg[k] = (agg[k] ?? 0) + 1;
    }
    offset += list.length;
    if (list.length < 40) break;
  }
  return { scanned: offset, agg };
}

export default async (ctx, client) => {
  const since = new Date(Date.now() - 3*24*3600*1000).toISOString();
  const out = {};
  for (const bid of [5, 71, 70, 20]) {
    const f = await client.operations.listRuns({ created_after: since, behavior_ids: [bid], status: 'failed', limit: 3 });
    const c = await client.operations.listRuns({ created_after: since, behavior_ids: [bid], status: 'completed', limit: 1 });
    const fl = f.runs ?? f.items ?? [];
    out[bid] = {
      failed_total: f.total ?? null,
      completed_total: c.total ?? null,
      errors: fl.map(x => ({ id: x.id, at: x.created_at, err: String(x.error ?? x.error_message ?? JSON.stringify(x.result ?? '')).slice(0, 400) })),
    };
  }
  return out;
}

export default async (ctx, client) => {
  const since = new Date(Date.now() - 7*24*3600*1000).toISOString();
  const out = {};
  for (const bid of [5, 71]) {
    const byDay = {};
    for (const st of ['failed','completed']) {
      let offset = 0;
      for (let p = 0; p < 6; p++) {
        const r = await client.operations.listRuns({ created_after: since, behavior_ids: [bid], status: st, limit: 40, offset });
        const list = r.runs ?? r.items ?? [];
        if (!list.length) break;
        for (const x of list) {
          const d = String(x.created_at).slice(0,10);
          byDay[d] = byDay[d] ?? { ok: 0, fail: 0 };
          if (st === 'failed') byDay[d].fail++; else byDay[d].ok++;
        }
        offset += list.length;
        if (list.length < 40) break;
      }
    }
    out[bid] = byDay;
  }
  return out;
}

