214	  // This is intentionally a stable, human-selected pairing slug. Never pick an
215	  // arbitrary online Chrome connection: that can stage a draft in the wrong
216	  // physical browser or signed-in account.
217	  const browsers = (await client.query(
218	    `SELECT c.id
